5	constexpr int32_t BLOCK_SIZE = 2048;
6	constexpr int32_t MAX_CORES = 20;
7	
8	at::Tensor gelu(const at::Tensor& x, c10::optional<std::string> approximate)
9	{
10	    TORCH_CHECK(x.is_contiguous(), "GELU input must be contiguous");
11	    TORCH_CHECK(x.scalar_type() == at::kFloat ||
12	                x.scalar_type() == at::kHalf ||
13	                x.scalar_type() == at::kBFloat16,
14	                "GELU unsupported dtype, expected float32/float16/bfloat16");
15	
16	    int32_t totalElements = static_cast<int32_t>(x.numel());
17	    int32_t numBlocks = (totalElements + BLOCK_SIZE - 1) / BLOCK_SIZE;
18	    int32_t usedCores = std::min(MAX_CORES, numBlocks);
19	    int32_t tasksPerCore = (numBlocks + usedCores - 1) / usedCores;
20	
21	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
22	    int32_t aivCoreNum = static_cast<int32_t>(ascendcPlatform->GetCoreNumAiv());
23	    if (aivCoreNum <= 0) aivCoreNum = MAX_CORES;
24	    usedCores = std::min(aivCoreNum, numBlocks);
25	    tasksPerCore = (numBlocks + usedCores - 1) / usedCores;
26	
27	    uint32_t blockDim = static_cast<uint32_t>(usedCores);
28	
29	    if (x.scalar_type() == at::kFloat) {
30	        at::Tensor y = at::empty_like(x);
31	        EXEC_KERNEL_CMD(gelu_fp32, blockDim, x, y, totalElements, BLOCK_SIZE, tasksPerCore);
32	        return y;
33	    } else if (x.scalar_type() == at::kHalf) {
34	        at::Tensor y = at::empty_like(x);
35	        EXEC_KERNEL_CMD(gelu_fp16, blockDim, x, y, totalElements, BLOCK_SIZE, tasksPerCore);
36	        return y;
37	    } else if (x.scalar_type() == at::kBFloat16) {
38	        // Convert bf16 to fp16 for kernel, then back
39	        at::Tensor xFp16 = x.to(at::kHalf);
40	        at::Tensor yFp16 = at::empty_like(xFp16);
41	        EXEC_KERNEL_CMD(gelu_fp16, blockDim, xFp16, yFp16, totalElements, BLOCK_SIZE, tasksPerCore);
42	        return yFp16.to(at::kBFloat16);
43	    }
44	
45	    return at::empty_like(x);
46	}
