3	using namespace AscendC;
4	
5	constexpr int32_t BLOCK_SIZE = 2048;
6	constexpr float SCALE = 0.79788456f;
7	constexpr float CUBIC = 0.044715f;
8	
9	template <typename T>
10	class KernelGelu {
11	public:
12	    __aicore__ inline KernelGelu() = default;
13	    __aicore__ inline void Init(
14	        GM_ADDR x, GM_ADDR y,
15	        int32_t totalElements, int32_t blockStart, int32_t blockEnd)
16	    {
17	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x), totalElements);
18	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(y), totalElements);
19	        blockStart_ = blockStart;
20	        blockEnd_ = blockEnd;
21	        totalElements_ = totalElements;
22	    }
23	
24	    __aicore__ inline void Process()
25	    {
26	        constexpr uint32_t ubBufSize = static_cast<uint32_t>(BLOCK_SIZE) * sizeof(T);
27	        LocalTensor<T> xLocal(TPosition::VECCALC, 0, ubBufSize);
28	        LocalTensor<T> yLocal(TPosition::VECCALC, ubBufSize, ubBufSize);
29	
30	        for (int32_t off = blockStart_; off < blockEnd_; off += BLOCK_SIZE) {
31	            int32_t valid = BLOCK_SIZE;
32	            if (off + BLOCK_SIZE > totalElements_) valid = totalElements_ - off;
33	            uint32_t u32Valid = static_cast<uint32_t>(valid);
34	
35	            // CopyIn: GM -> UB
36	            DataCopy(xLocal, xGM_[off], u32Valid);
37	            PipeBarrier<PIPE_ALL>();
38	
39	            // Compute GELU elementwise
40	            for (int32_t i = 0; i < valid; i++) {
41	                if constexpr (std::is_same_v<T, float>) {
42	                    float val = xLocal.GetValue(i);
43	                    float x3 = val * val * val;
44	                    float u = SCALE * (val + CUBIC * x3);
45	                    float expNeg2u = exp(-2.0f * u);
46	                    float gelu = val / (1.0f + expNeg2u);
47	                    yLocal.SetValue(i, gelu);
48	                } else {
49	                    float val = static_cast<float>(xLocal.GetValue(i));
50	                    float x3 = val * val * val;
51	                    float u = SCALE * (val + CUBIC * x3);
52	                    float expNeg2u = exp(-2.0f * u);
53	                    float gelu = val / (1.0f + expNeg2u);
54	                    yLocal.SetValue(i, static_cast<T>(gelu));
55	                }
56	            }
57	            PipeBarrier<PIPE_ALL>();
58	
59	            // CopyOut: UB -> GM
60	            DataCopy(yGM_[off], yLocal, u32Valid);
61	            PipeBarrier<PIPE_ALL>();
62	        }
63	    }
64	
65	private:
66	    GlobalTensor<T> xGM_;
67	    GlobalTensor<T> yGM_;
68	    int32_t blockStart_;
69	    int32_t blockEnd_;
70	    int32_t totalElements_;
71	};
