73	extern "C" __global__ __aicore__ void gelu_fp32(
74	    GM_ADDR x, GM_ADDR y, int32_t totalElements, int32_t blockSize, int32_t tasksPerCore)
75	{
76	    int32_t cid = GetBlockIdx() / GetSubBlockNum();
77	    int32_t start = cid * tasksPerCore * blockSize;
78	    int32_t end = start + tasksPerCore * blockSize;
79	    if (end > totalElements) end = totalElements;
80	    KernelGelu<float> op;
81	    op.Init(x, y, totalElements, start, end);
82	    op.Process();
83	}
