{"content": "#include "kernel_operator.h"

using namespace AscendC;

constexpr int32_t BLOCK_SIZE = 2048;
constexpr float SCALE = 0.79788456f;
constexpr float CUBIC = 0.044715f;

template <typename T>
class KernelGelu {
public:
    __aicore__ inline KernelGelu() = default;
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t totalElements, int32_t blockStart, int32_t blockEnd)
    {
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x), totalElements);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(y), totalElements);
        blockStart_ = blockStart;
        blockEnd_ = blockEnd;
        totalElements_ = totalElements;
    }

    __aicore__ inline void Process()
    {
        // UB buffer layout (max 40KB for fp32, well within 192KB UB):
        //   x_typed   : BLOCK_SIZE * sizeof(T)     — typed input
        //   x_fp32    : BLOCK_SIZE * 4             — fp32 input
        //   x3        : BLOCK_SIZE * 4             — x^3
        //   u         : BLOCK_SIZE * 4             — tanh argument
        //   expBuf    : BLOCK_SIZE * 4             — exp(-2u)
        //   oneBuf    : BLOCK_SIZE * 4             — 1.0
        //   denom     : BLOCK_SIZE * 4             — 1 + exp(-2u)
        //   y_fp32    : BLOCK_SIZE * 4             — fp32 output
        //   y_typed   : BLOCK_SIZE * sizeof(T)     — typed output
        constexpr uint32_t fp32Size = static_cast<uint32_t>(BLOCK_SIZE) * sizeof(float);
        constexpr uint32_t typedSize = static_cast<uint32_t>(BLOCK_SIZE) * sizeof(T);

        LocalTensor<T> xTypedUb(TPosition::VECCALC, 0, typedSize);
        LocalTensor<float> xFp32Ub(TPosition::VECCALC, typedSize, fp32Size);
        LocalTensor<float> x3Ub(TPosition::VECCALC, typedSize + fp32Size, fp32Size);
        LocalTensor<float> uUb(TPosition::VECCALC, typedSize + 2 * fp32Size, fp32Size);
        LocalTensor<float> expUb(TPosition::VECCALC, typedSize + 3 * fp32Size, fp32Size);
        LocalTensor<float> oneUb(TPosition::VECCALC, typedSize + 4 * fp32Size, fp32Size);
        LocalTensor<float> denomUb(TPosition::VECCALC, typedSize + 5 * fp32Size, fp32Size);
        LocalTensor<float> yFp32Ub(TPosition::VECCALC, typedSize + 6 * fp32Size, fp32Size);
        LocalTensor<T> yTypedUb(TPosition::VECCALC, typedSize + 7 * fp32Size, typedSize);

        for (int32_t off = blockStart_; off < blockEnd_; off += BLOCK_SIZE) {
            int32_t valid = BLOCK_SIZE;
            if (off + BLOCK_SIZE > totalElements_) valid = totalElements_ - off;
            uint32_t u32Valid = static_cast<uint32_t>(valid);

            // ---- Load input ----
            DataCopy(xTypedUb, xGM_[off], u32Valid);
            PipeBarrier<PIPE_ALL>();

            // ---- Cast to fp32 if needed ----
            if constexpr (!std::is_same_v<T, float>) {
                TileCast(xFp32Ub, xTypedUb, CAST_NONE, u32Valid);
            } else {
                DataCopy(xFp32Ub, xTypedUb, u32Valid);
                PipeBarrier<PIPE_ALL>();
            }

            // ---- GELU computation (all in fp32) ----
            // x3 = x * x * x
            Mul(x3Ub, xFp32Ub, xFp32Ub, u32Valid);
            Mul(x3Ub, x3Ub, xFp32Ub, u32Valid);

            // u = SCALE * (x + CUBIC * x3)
            Mul(x3Ub, x3Ub, T.float32(CUBIC), u32Valid);
            Add(uUb, xFp32Ub, x3Ub, u32Valid);
            Mul(uUb, uUb, T.float32(SCALE), u32Valid);

            // denom = 1 + exp(-2 * u)
            Mul(expUb, uUb, T.float32(-2.0f), u32Valid);
            Exp(expUb, expUb, u32Valid);
            Fill(oneUb, T.float32(1.0f), u32Valid);
            Add(denomUb, oneUb, expUb, u32Valid);

            // y = x / (1 + exp(-2u))
            Div(yFp32Ub, xFp32Ub, denomUb, u32Valid);

            // ---- Cast back to typed dtype ----
            if constexpr (!std::is_same_v<T, float>) {
                TileCast(yTypedUb, yFp32Ub, CAST_ROUND, u32Valid);
            } else {
                DataCopy(yTypedUb, yFp32Ub, u32Valid);
                PipeBarrier<PIPE_ALL>();
            }

            // ---- Store output ----
            DataCopy(yGM_[off], yTypedUb, u32Valid);
            PipeBarrier<PIPE_ALL>();
        }
    }

private:
    GlobalTensor<T> xGM_;
    GlobalTensor<T> yGM_;
    int32_t blockStart_;
    int32_t blockEnd_;
    int32_t totalElements_;
};

extern "C" __global__ __aicore__ void gelu_fp32(
    GM_ADDR x, GM_ADDR y, int32_t totalElements, int32_t blockSize, int32_t tasksPerCore)
{
    int32_t cid = GetBlockIdx() / GetSubBlockNum();
    int32_t start = cid * tasksPerCore * blockSize;
    int32_t end = start + tasksPerCore * blockSize;
    if (end > totalElements) end = totalElements;
    KernelGelu<float> op;
    op.Init(x, y, totalElements, start, end);
    op.Process();
}

extern "C" __global__ __aicore__ void gelu_fp16(
    GM_ADDR x, GM_ADDR y, int32_t totalElements, int32_t blockSize, int32_t tasksPerCore)
{
    int32_t cid = GetBlockIdx() / GetSubBlockNum();
    int32_t start = cid * tasksPerCore * blockSize;
    int32_t end = start + tasksPerCore * blockSize;
    if (end > totalElements) end = totalElements;
    KernelGelu<half> op;
    op.Init(x, y, totalElements, start, end);
    op.Process();
}
