using namespace AscendC;

constexpr int32_t BLOCK_SIZE = 2048;
constexpr float SCALE = 0.79788456f;
constexpr float CUBIC = 0.044715f;

template <typename T>
class KernelGelu {
public:
    __aicore__ inline KernelGelu() = default;
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t totalElements, int32_t blockStart, int32_t blockEnd)
    {
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x), totalElements);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(y), totalElements);
        blockStart_ = blockStart;
        blockEnd_ = blockEnd;
        totalElements_ = totalElements;
    }

    __aicore__ inline void Process()
    {
        // UB buffer layout:
        //   xTyped   : BLOCK_SIZE * sizeof(T)    — typed I/O
        //   xFp32    : BLOCK_SIZE * 4             — fp32 input
        //   x3       : BLOCK_SIZE * 4             — x^3
        //   u        : BLOCK_SIZE * 4             — tanh arg
        //   expBuf   : BLOCK_SIZE * 4             — exp(-2u) / -2u scratch
        //   yFp32    : BLOCK_SIZE * 4             — fp32 output
        constexpr uint32_t fp32Sz = static_cast<uint32_t>(BLOCK_SIZE) * sizeof(float);
        constexpr uint32_t typedSz = static_cast<uint32_t>(BLOCK_SIZE) * sizeof(T);

        LocalTensor<T> xTyped(TPosition::VECCALC, 0, typedSz);
        LocalTensor<float> xFp32(TPosition::VECCALC, typedSz, fp32Sz);
        LocalTensor<float> x3(TPosition::VECCALC, typedSz + fp32Sz, fp32Sz);
        LocalTensor<float> u(TPosition::VECCALC, typedSz + 2 * fp32Sz, fp32Sz);
        LocalTensor<float> expBuf(TPosition::VECCALC, typedSz + 3 * fp32Sz, fp32Sz);
        LocalTensor<float> yFp32(TPosition::VECCALC, typedSz + 4 * fp32Sz, fp32Sz);

        for (int32_t off = blockStart_; off < blockEnd_; off += BLOCK_SIZE) {
            int32_t valid = BLOCK_SIZE;
            if (off + BLOCK_SIZE > totalElements_) valid = totalElements_ - off;
            uint32_t u32Valid = static_cast<uint32_t>(valid);

            // ---- Load input ----
            DataCopy(xTyped, xGM_[off], u32Valid);
            PipeBarrier<PIPE_ALL>();

            // ---- Cast to fp32 ----
            if constexpr (std::is_same_v<T, float>) {
                DataCopy(xFp32, xTyped, u32Valid);
            } else {
                AscendC::Cast(xFp32, xTyped, AscendC::RoundMode::CAST_NONE, u32Valid);
            }
            PipeBarrier<PIPE_ALL>();

            // ---- GELU computation in fp32 ----
            // x3 = x * x * x
            for (int32_t i = 0; i < valid; i++) {
                float val = xFp32.GetValue(i);
                x3.SetValue(i, val * val * val);
            }

            // u = SCALE * (x + CUBIC * x3)
            for (int32_t i = 0; i < valid; i++) {
                float val = xFp32.GetValue(i);
                float x3v = x3.GetValue(i);
                u.SetValue(i, SCALE * (val + CUBIC * x3v));
            }

            // expBuf = exp(-2 * u)  [vector Exp]
            for (int32_t i = 0; i < valid; i++) {
                expBuf.SetValue(i, -2.0f * u.GetValue(i));
            }
            Exp(expBuf, expBuf, u32Valid);

            // y = x / (1 + exp(-2u))
            for (int32_t i = 0; i < valid; i++) {
                float val = xFp32.GetValue(i);
                float denom = 1.0f + expBuf.GetValue(i);
                yFp32.SetValue(i, val / denom);
            }

            // ---- Cast back to typed ----
            if constexpr (std::is_same_v<T, float>) {
                DataCopy(xTyped, yFp32, u32Valid);
            } else {
                AscendC::Cast(xTyped, yFp32, AscendC::RoundMode::CAST_ROUND, u32Valid);
            }
            PipeBarrier<PIPE_ALL>();

            // ---- Store output ----
            DataCopy(yGM_[off], xTyped, u32Valid);
            PipeBarrier<PIPE_ALL>();
        }
    }

private:
    GlobalTensor<T> xGM_;
    GlobalTensor<T> yGM_;
    int32_t blockStart_;
    int32_t blockEnd_;
    int32_t totalElements_;
};

extern "C" __global__ __aicore__ void gelu_fp32(
    GM_ADDR x, GM_ADDR y, int32_t totalElements, int32_t blockSize, int32_t tasksPerCore)
{
    int32_t cid = GetBlockIdx() / GetSubBlockNum();
    int32_t start = cid * tasksPerCore * blockSize;
    int32_t end = start + tasksPerCore * blockSize;
    if (end > totalElements) end = totalElements;
    KernelGelu<float> op;
    op.Init(x, y, totalElements, start, end);
    op.Process();
}

extern "C" __global__ __aicore__ void gelu_fp16(
    GM_ADDR x, GM_ADDR y, int32_t totalElements, int32_t blockSize, int32_t tasksPerCore)
{
    int32_t cid = GetBlockIdx() / GetSubBlockNum();
    int32_t start = cid * tasksPerCore * blockSize;
    int32_t end = start + tasksPerCore * blockSize;
    if (end > totalElements) end = totalElements;
    KernelGelu<half> op;
    op.Init(x, y, totalElements, start, end);
    op.Process();
}
