using namespace AscendC;

constexpr int32_t BLOCK_SIZE = 2048;

template <typename T>
class KernelGelu {
public:
    __aicore__ inline KernelGelu() = default;
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t totalElements, int32_t blockStart, int32_t blockEnd)
    {
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x), totalElements);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(y), totalElements);
        blockStart_ = blockStart;
        blockEnd_ = blockEnd;
        totalElements_ = totalElements;
    }

    __aicore__ inline void Process()
    {
        constexpr uint32_t ubSz = static_cast<uint32_t>(BLOCK_SIZE) * sizeof(T);
        LocalTensor<T> xTyped(TPosition::VECCALC, 0, ubSz);

        for (int32_t off = blockStart_; off < blockEnd_; off += BLOCK_SIZE) {
            int32_t valid = BLOCK_SIZE;
            if (off + BLOCK_SIZE > totalElements_) valid = totalElements_ - off;
            uint32_t u32Valid = static_cast<uint32_t>(valid);

            // DEBUG: write constant value to output (no read)
            for (int32_t i = 0; i < valid; i++) {
                xTyped.SetValue(i, static_cast<T>(1.0f));
            }
            PipeBarrier<PIPE_ALL>();
            DataCopy(yGM_[off], xTyped, u32Valid);
            PipeBarrier<PIPE_ALL>();
        }
    }

private:
    GlobalTensor<T> xGM_;
    GlobalTensor<T> yGM_;
    int32_t blockStart_;
    int32_t blockEnd_;
    int32_t totalElements_;
};

